/**
 * "Cure" the masonry: let every course reach true static equilibrium, then
 * record that pose as the reference. Bricks are laid at exact contact, so
 * without this a tall wall visibly slumps by the accumulated contact slop the
 * instant it is woken — and the integrity readout would report damage the car
 * never caused. Purely a build-time step; it is not part of the timed run.
 */
function settleWall(world) {
  const onM = world.onManifold;
  world.onManifold = null;
  for (const b of EX.bricks) b.wake();
  for (let i = 0; i < 28; i++) world.step(1 / 120, 8, 6);
  for (const b of EX.bricks) {
    b.vx = b.vy = b.av = 0;
    b.ox = b.px; b.oy = b.py; b.oang = b.ang;
    b.sleep();
  }
