  for (let i = 0; i < m.count; i++) {
    const p = m.pts[i];
    const dvx = (B.vx - B.av * p.rby) - (A.vx - A.av * p.ray);
    const dvy = (B.vy + B.av * p.rbx) - (A.vy + A.av * p.rax);
    const vt = dvx * tx + dvy * ty;
    let dl = -p.tmass * vt;
    const maxF = m.fric * p.ni;
    const oldT = p.ti;
    p.ti = clamp(oldT + dl, -maxF, maxF);
    dl = p.ti - oldT;
    const ix = dl * tx, iy = dl * ty;
    A.vx -= ix * A.invMass; A.vy -= iy * A.invMass;
    A.av -= A.invI * (p.rax * iy - p.ray * ix);
    B.vx += ix * B.invMass; B.vy += iy * B.invMass;
    B.av += B.invI * (p.rbx * iy - p.rby * ix);
  }

  // ---- normal
  if (m.block) {
    // Simultaneous 2-point solve: find x >= 0 with A*x + b = 0, trying
    // each active set in turn (both points, either one, neither).
    const p1 = m.pts[0], p2 = m.pts[1];
    const a1 = p1.ni, a2 = p2.ni;
    let dvx = (B.vx - B.av * p1.rby) - (A.vx - A.av * p1.ray);
    let dvy = (B.vy + B.av * p1.rbx) - (A.vy + A.av * p1.rax);
    const vn1 = dvx * nx + dvy * ny;
    dvx = (B.vx - B.av * p2.rby) - (A.vx - A.av * p2.ray);
    dvy = (B.vy + B.av * p2.rbx) - (A.vy + A.av * p2.rax);
    const vn2 = dvx * nx + dvy * ny;

    const b1 = vn1 - p1.vbias - (m.k11 * a1 + m.k12 * a2);
    const b2 = vn2 - p2.vbias - (m.k12 * a1 + m.k22 * a2);

    let x1 = -(m.k22 * b1 - m.k12 * b2) * m.invDet;
    let x2 = -(m.k11 * b2 - m.k12 * b1) * m.invDet;
    let ok = x1 >= 0 && x2 >= 0;
    if (!ok) { x1 = -b1 / m.k11; x2 = 0; ok = x1 >= 0 && m.k12 * x1 + b2 >= 0; }
    if (!ok) { x1 = 0; x2 = -b2 / m.k22; ok = x2 >= 0 && m.k12 * x2 + b1 >= 0; }
    if (!ok) { x1 = 0; x2 = 0; ok = b1 >= 0 && b2 >= 0; }

    if (ok) {
      const d1 = x1 - a1, d2 = x2 - a2;
      const ix = (d1 + d2) * nx, iy = (d1 + d2) * ny;
      A.vx -= ix * A.invMass; A.vy -= iy * A.invMass;
      A.av -= A.invI * (p1.rax * (d1 * ny) - p1.ray * (d1 * nx)
