    dvx = (B.vx - B.av * p2.rby) - (A.vx - A.av * p2.ray);
    dvy = (B.vy + B.av * p2.rbx) - (A.vy + A.av * p2.rax);
    const vn2 = dvx * nx + dvy * ny;

    const b1 = vn1 - p1.vbias - (m.k11 * a1 + m.k12 * a2);
    const b2 = vn2 - p2.vbias - (m.k12 * a1 + m.k22 * a2);

    let x1 = -(m.k22 * b1 - m.k12 * b2) * m.invDet;
    let x2 = -(m.k11 * b2 - m.k12 * b1) * m.invDet;
    let ok = x1 >= 0 && x2 >= 0;
    if (!ok) { x1 = -b1 / m.k11; x2 = 0; ok = x1 >= 0 && m.k12 * x1 + b2 >= 0; }
    if (!ok) { x1 = 0; x2 = -b2 / m.k22; ok = x2 >= 0 && m.k12 * x2 + b1 >= 0; }
