      B.vx += ix * B.invMass; B.vy += iy * B.invMass;
      B.av += B.invI * (p1.rbx * (d1 * ny) - p1.rby * (d1 * nx)
                      + p2.rbx * (d2 * ny) - p2.rby * (d2 * nx));
      p1.ni = x1; p2.ni = x2;
    }
  } else {
    for (let i = 0; i < m.count; i++) {
      const p = m.pts[i];
      const dvx = (B.vx - B.av * p.rby) - (A.vx - A.av * p.ray);
      const dvy = (B.vy + B.av * p.rbx) - (A.vy + A.av * p.rax);
      const vn = dvx * nx + dvy * ny;
