      B.vx += ix * B.invMass; B.vy += iy * B.invMass;
      B.av += B.invI * (p.rbx * iy - p.rby * ix);
    }
  }
  if (last) for (let i = 0; i < m.count; i++) m.totalImpulse += m.pts[i].ni;
}

