require('./harness.js');
const { World, Body, S } = global.__X;

function column(n) {
  const w = new World();
  w.gravity = 9.81;
  const bw = 0.5, bh = 0.24, m = 2.5;
  const ground = new Body(0, -0.5, 200, 0.5, 0, true);
  ground.fric = 0.85; ground.rest = 0; ground.layer = -1;
  w.add(ground);
  const bricks = [];
  for (let i = 0; i < n; i++) {
    const b = new Body(0, bh / 2 + i * bh, bw / 2, bh / 2, m, false);
    b.fric = 0.72; b.rest = 0.18; b.layer = 0;
    w.add(b); bricks.push(b);
  }
  return { w, bricks, bh, m };
}

function pe(bricks, bh) {
  let e = 0;
  for (const b of bricks) e += b.mass * 9.81 * (b.py - bh / 2);
  return e;
}
function ke(bricks) {
  let e = 0;
  for (const b of bricks) e += 0.5 * b.mass * (b.vx * b.vx + b.vy * b.vy) + 0.5 * b.I * b.av * b.av;
  return e;
}

console.log('--- energy conservation of a resting column (2 s) ---');
for (const n of [2, 4, 8, 16, 24]) {
  const { w, bricks, bh } = column(n);
  const e0 = pe(bricks, bh);
  let peakKE = 0, maxAng = 0, minMan = 1e9;
  for (let i = 0; i < 240; i++) {
    w.step(1 / 60, 12, 4);
    const anyAwake = bricks.some(b => b.awake);
    if (anyAwake) minMan = Math.min(minMan, w.manifolds.size);
    peakKE = Math.max(peakKE, ke(bricks));
    for (const b of bricks) maxAng = Math.max(maxAng, Math.abs(b.ang));
  }
  const e1 = pe(bricks, bh) + ke(bricks);
  let sink = 0;
  for (let i = 0; i < n; i++) sink = Math.max(sink, (bh / 2 + i * bh) - bricks[i].py);
  console.log(`  n=${String(n).padStart(2)}  dE ${(e1 - e0).toFixed(4).padStart(10)}J  peakKE ${peakKE.toExponential(2).padStart(10)}  maxAng ${maxAng.toExponential(2).padStart(10)}  sink ${(sink * 1000).toFixed(3).padStart(9)}mm  manifolds min ${minMan === 1e9 ? 'n/a' : minMan} (expect ${n})`);
}

