require('./harness.js');
const { World, Body } = global.__X;

const BW = 0.5, BH = 0.24, M = 2.5, G = 9.81;

function column(n) {
  const w = new World(G, 0.6);
  w.add(new Body({ x: 0, y: -0.5, hw: 200, hh: 0.5, isStatic: true, fric: 0.85, rest: 0, layer: -1 }));
  const bricks = [];
  for (let i = 0; i < n; i++) {
    const b = new Body({ x: 0, y: BH / 2 + i * BH, hw: BW / 2, hh: BH / 2, mass: M, fric: 0.72, rest: 0.18, layer: 0 });
    w.add(b); bricks.push(b);
  }
  return { w, bricks };
}

const pe = bs => bs.reduce((e, b) => e + b.mass * G * (b.py - BH / 2), 0);
const ke = bs => bs.reduce((e, b) => e + 0.5 * b.mass * (b.vx * b.vx + b.vy * b.vy) + 0.5 * b.inertia * b.av * b.av, 0);

console.log('--- energy conservation of a resting column (2 s) ---');
for (const n of [2, 4, 8, 16, 24]) {
  const { w, bricks } = column(n);
  const e0 = pe(bricks);
  let peakKE = 0, maxAng = 0, minMan = Infinity;
  for (let i = 0; i < 240; i++) {
