    peakKE = Math.max(peakKE, ke(bricks));
    for (const b of bricks) maxAng = Math.max(maxAng, Math.abs(b.ang));
  }
  const e1 = pe(bricks) + ke(bricks);
  let sink = 0;
  for (let i = 0; i < n; i++) sink = Math.max(sink, (BH / 2 + i * BH) - bricks[i].py);
