prestep(invDt) {
  for (const m of this.manifolds.values()) {
    const A = m.A, B = m.B, nx = m.nx, ny = m.ny;
    const ov = this.frictionOverride && this.frictionOverride(A, B);
    m.fric = ov === null || ov === undefined ? Math.sqrt(A.fric * B.fric) : ov;
    m.rest = Math.min(A.rest, B.rest);
    m.totalImpulse = 0;
    const tx = -ny, ty = nx;

    for (let i = 0; i < m.count; i++) {
      const p = m.pts[i];
      p.rax = p.x - A.px; p.ray = p.y - A.py;
      p.rbx = p.x - B.px; p.rby = p.y - B.py;
      // cache anchors in local space for the position pass
      p.lax =  p.rax * A.c + p.ray * A.s;
      p.lay = -p.rax * A.s + p.ray * A.c;
      p.lbx =  p.rbx * B.c + p.rby * B.s;
      p.lby = -p.rbx * B.s + p.rby * B.c;

      const rnA = p.rax * ny - p.ray * nx;
      const rnB = p.rbx * ny - p.rby * nx;
      const kn = A.invMass + B.invMass + A.invI * rnA * rnA + B.invI * rnB * rnB;
      p.nmass = kn > 0 ? 1 / kn : 0;

      const rtA = p.rax * ty - p.ray * tx;
      const rtB = p.rbx * ty - p.rby * tx;
      const kt = A.invMass + B.invMass + A.invI * rtA * rtA + B.invI * rtB * rtB;
      p.tmass = kt > 0 ? 1 / kt : 0;

      const dvx = (B.vx - B.av * p.rby) - (A.vx - A.av * p.ray);
      const dvy = (B.vy + B.av * p.rbx) - (A.vy + A.av * p.rax);
      const vn = dvx * nx + dvy * ny;

      if (p.sep > 0) p.vbias = -p.sep * invDt;              // speculative limit
      else if (vn < -REST_THRESH) p.vbias = -m.rest * vn;   // bounce
      else p.vbias = 0;

      // warm start
      const px = p.ni * nx + p.ti * tx;
      const py = p.ni * ny + p.ti * ty;
      A.vx -= px * A.invMass; A.vy -= py * A.invMass;
      A.av -= A.invI * (p.rax * py - p.ray * px);
      B.vx += px * B.invMass; B.vy += py * B.invMass;
      B.av += B.invI * (p.rbx * py - p.rby * px);
