require('./harness.js');
const { World, Body } = global.__X;
const BW = 0.5, BH = 0.24, M = 2.5, G = 9.81;

const w = new World(-G, 0.6);
const ground = new Body({ x: 0, y: -0.5, hw: 200, hh: 0.5, isStatic: true, fric: 0.85, rest: 0, layer: -1 });
ground.tag = 'ground';
w.add(ground);
const bricks = [];
const n = +(process.argv[2] || 8);
for (let i = 0; i < n; i++) {
  const b = new Body({ x: 0, y: BH / 2 + i * BH, hw: BW / 2, hh: BH / 2, mass: M, fric: 0.72, rest: 0.18, layer: 0 });
  b.tag = 'b' + i;
  w.add(b); bricks.push(b);
}

for (let s = 0; s < 3; s++) {
  w.step(1 / 60, 12, 4);
  console.log(`\n===== after step ${s} =====`);
  const ms = [...w.manifolds.values()].sort((a, b) => (a.A.py + a.B.py) - (b.A.py + b.B.py));
  for (const m of ms) {
    const pts = [];
    for (let i = 0; i < m.count; i++) {
      const p = m.pts[i];
      pts.push(`{x:${p.x.toFixed(6)} sep:${p.sep.toExponential(3)} fid:${p.fid} ni:${p.ni.toFixed(6)} ti:${p.ti.toExponential(2)}}`);
    }
    console.log(` ${(m.A.tag + '/' + m.B.tag).padEnd(12)} n=(${m.nx.toFixed(2)},${m.ny.toFixed(2)}) blk=${m.block ? 1 : 0} cnt=${m.count} ${pts.join(' ')}`);
  }
  console.log(' bodies:');
  for (const b of bricks) console.log(`  ${b.tag}: y ${b.py.toFixed(7)} x ${b.px.toExponential(3)} ang ${b.ang.toExponential(3)} vy ${b.vy.toExponential(3)} vx ${b.vx.toExponential(3)} av ${b.av.toExponential(3)}`);
}

