// Minimal DOM stub so the simulation script can be evaluated in node.
const mkEl = () => {
  const e = {
    style:{}, dataset:{}, classList:{_s:new Set(),add(x){this._s.add(x)},remove(x){this._s.delete(x)},toggle(x){this._s.has(x)?this._s.delete(x):this._s.add(x)},contains(x){return this._s.has(x)}},
    children:[], textContent:"", innerHTML:"", value:"0",
    appendChild(c){this.children.push(c); return c;},
    addEventListener(){}, querySelector(){ return mkEl(); }, querySelectorAll(){ return []; },
  };
  return e;
};
const ctxStub = new Proxy({}, { get: (t,p) => {
  if (p === 'canvas') return { width:1440, height:900 };
  return (...a) => ({ addColorStop(){} });
}});
global.document = {
  getElementById: () => mkEl(),
  createElement: () => mkEl(),
  addEventListener(){},
};
global.window = { innerWidth:1440, innerHeight:900, devicePixelRatio:1, addEventListener(){} };
global.performance = { now: () => 0 };
global.requestAnimationFrame = () => 0;
// patch canvas getContext
const origGet = global.document.getElementById;
global.document.getElementById = (id) => {
  const e = origGet(id);
  if (id === 'cv') e.getContext = () => ctxStub;
  return e;
};

const fs = require('fs');
let src = fs.readFileSync('sim.js','utf8');
// expose internals for the test harness
src += "\nglobal.__X = { EX, S, DEFAULTS, buildScene, startTest, simulate, countMoving, countDisplaced, kineticEnergy, World, Body, PARAMS };\n";
eval(src);
module.exports = global.__X;

