// Log the state after every velocity iteration of one chosen step.
const fs = require('fs');
const orig = fs.readFileSync('sim.js', 'utf8');
// inject a per-iteration hook at the close of the iteration loop
const needle = `        if (last) for (let i = 0; i < m.count; i++) m.totalImpulse += m.pts[i].ni;
      }
    }
  }`;
if (!orig.includes(needle)) throw new Error('hook anchor not found');
const patched = orig.replace(needle, `        if (last) for (let i = 0; i < m.count; i++) m.totalImpulse += m.pts[i].ni;
      }
      if (this.onIter) this.onIter(it, this);
    }
  }`);
fs.writeFileSync('sim.dbg.js', patched);

// harness that loads sim.dbg.js
let h = fs.readFileSync('harness.js', 'utf8').replace("readFileSync('sim.js'", "readFileSync('sim.dbg.js'");
fs.writeFileSync('harness.dbg.js', h);

require('./harness.dbg.js');
const { World, Body } = global.__X;
const BW = 0.5, BH = 0.24, M = 2.5, G = 9.81;

const w = new World(-G, 0.6);
const ground = new Body({ x: 0, y: -0.5, hw: 200, hh: 0.5, isStatic: true, fric: 0.85, rest: 0, layer: -1 });
ground.tag = 'ground'; w.add(ground);
const bricks = [];
const n = 4;
for (let i = 0; i < n; i++) {
  const b = new Body({ x: 0, y: BH / 2 + i * BH, hw: BW / 2, hh: BH / 2, mass: M, fric: 0.72, rest: 0.18, layer: 0 });
  b.tag = 'b' + i; w.add(b); bricks.push(b);
}

const watch = +(process.argv[2] || 2);
let step = 0;
w.onIter = (it, W) => {
  if (step !== watch) return;
  const ms = [...W.manifolds.values()].sort((a, b) => (a.A.py + a.B.py) - (b.A.py + b.B.py));
  const parts = ms.map(m => {
    const a = m.pts[0], b = m.count > 1 ? m.pts[1] : null;
    return `${m.A.tag}/${m.B.tag} ni[${a.ni.toFixed(4)},${b ? b.ni.toFixed(4) : '-'}] ti[${a.ti.toExponential(1)},${b ? b.ti.toExponential(1) : '-'}]`;
  });
  console.log(`  it${String(it).padStart(2)}  ${parts.join('  |  ')}`);
  console.log(`        av: ${bricks.map(b => b.av.toExponential(2)).join(' ')}   vx: ${bricks.map(b => b.vx.toExponential(2)).join(' ')}`);
};

for (step = 0; step <= watch; step++) {
  if (step === watch) console.log(`===== velocity iterations of step ${watch} =====`);
  w.step(1 / 60, 12, 4);
}

