const { World, Body } = global.__X;
const BH = 0.24;

function run(n, posIters, velIters, seconds) {
  const w = new World(-9.81, 0.6);
  w.add(new Body({ x: 0, y: -0.5, hw: 200, hh: 0.5, isStatic: true, fric: 0.85, rest: 0, layer: -1 }));
  const bricks = [];
  for (let i = 0; i < n; i++) {
    const b = new Body({ x: 0, y: BH / 2 + i * BH, hw: 0.25, hh: BH / 2, mass: 2.5, fric: 0.72, rest: 0.18, layer: 0 });
