require('./harness.js');
const { World, Body } = global.__X;
const BH = 0.24;

function build(n) {
  const w = new World(-9.81, 0.6);
  w.add(new Body({ x: 0, y: -0.5, hw: 200, hh: 0.5, isStatic: true, fric: 0.85, rest: 0, layer: -1 }));
  const bricks = [];
  for (let i = 0; i < n; i++) {
    const b = new Body({ x: 0, y: BH / 2 + i * BH, hw: 0.25, hh: BH / 2, mass: 2.5, fric: 0.72, rest: 0.18, layer: 0 });
    b.noSleep = true; w.add(b); bricks.push(b);
  }
  return { w, bricks };
}

// residual drift after settling: wake and run 3 s, measure max move from settled pose
function drift(n, settle) {
  const { w, bricks } = build(n);
  settle(w, bricks);
  const pose = bricks.map(b => ({ x: b.px, y: b.py }));
  let d = 0;
  for (let i = 0; i < 180; i++) {
    w.step(1 / 60, 12, 4);
    for (let j = 0; j < n; j++) d = Math.max(d, Math.hypot(bricks[j].px - pose[j].x, bricks[j].py - pose[j].y));
  }
  return d * 1000;
}

const damped = (steps, vi, pi) => (w, bricks) => {
  for (let i = 0; i < steps; i++) {
    w.step(1 / 60, vi, pi);
    for (const b of bricks) { b.vx = b.vy = b.av = 0; }
  }
};
const plain = (steps, vi, pi) => (w) => { for (let i = 0; i < steps; i++) w.step(1 / 60, vi, pi); };

console.log('residual drift (mm) over 3 s after settling');
for (const n of [8, 16, 24]) {
  const row = [];
  for (const s of [0, 8, 16, 24, 40, 60]) row.push(`d${s}:${drift(n, damped(s, 10, 6)).toFixed(2).padStart(7)}`);
  console.log(`  n=${String(n).padStart(2)} damped   ${row.join('  ')}`);
  const row2 = [];
  for (const s of [8, 24, 60, 120]) row2.push(`p${s}:${drift(n, plain(s, 10, 6)).toFixed(2).padStart(7)}`);
  console.log(`  n=${String(n).padStart(2)} plain    ${row2.join('  ')}`);
}

