// Sweep SLOP / BAUMGARTE against a resting stack: equilibrium sink + residual jitter.
const fs = require('fs');
const base = fs.readFileSync('sim.js', 'utf8');

function variant(slop, baum) {
  const src = base
    .replace(/const SLOP\s*=\s*[0-9.]+;/, `const SLOP = ${slop};`)
    .replace(/const BAUMGARTE\s*=\s*[0-9.]+;/, `const BAUMGARTE = ${baum};`);
  fs.writeFileSync('sim.var.js', src);
  fs.writeFileSync('harness.var.js', fs.readFileSync('harness.js', 'utf8').replace("readFileSync('sim.js'", "readFileSync('sim.var.js'"));
  for (const k of Object.keys(require.cache)) delete require.cache[k];
  delete global.__X;
  require('./harness.var.js');
  return global.__X;
}

const BH = 0.24;
function probe(X, n, seconds) {
  const { World, Body } = X;
  const w = new World(-9.81, 0.6);
  w.add(new Body({ x: 0, y: -0.5, hw: 200, hh: 0.5, isStatic: true, fric: 0.85, rest: 0, layer: -1 }));
  const bricks = [];
  for (let i = 0; i < n; i++) {
    const b = new Body({ x: 0, y: BH / 2 + i * BH, hw: 0.25, hh: BH / 2, mass: 2.5, fric: 0.72, rest: 0.18, layer: 0 });
    b.noSleep = true; w.add(b); bricks.push(b);
  }
  const steps = Math.round(seconds * 60);
  let jitter = 0, maxAng = 0;
  for (let i = 0; i < steps; i++) {
    w.step(1 / 60, 12, 4);
    if (i > steps * 0.6) for (const b of bricks) {
      jitter = Math.max(jitter, Math.hypot(b.vx, b.vy));
      maxAng = Math.max(maxAng, Math.abs(b.ang));
    }
  }
  const sink = ((BH / 2 + (n - 1) * BH) - bricks[n - 1].py) * 1000;
  return { sink, jitter, maxAng };
}

console.log('SLOP / BAUMGARTE sweep — sink(mm) of top brick, steady-state jitter(m/s), maxAng(rad)');
for (const slop of [0.0035, 0.002, 0.001, 0.0005, 0.0002]) {
  for (const baum of [0.22, 0.4]) {
    const X = variant(slop, baum);
    const parts = [8, 16].map(n => {
      const r = probe(X, n, 4);
      return `n=${n}: sink ${r.sink.toFixed(2).padStart(6)}mm jit ${r.jitter.toExponential(1)} ang ${r.maxAng.toExponential(1)}`;
    });
    console.log(`  SLOP=${String(slop).padEnd(7)} B=${String(baum).padEnd(5)} ${parts.join('   ')}`);
  }
}

