function settleWall(world) {
  const onM = world.onManifold;
  world.onManifold = null;
  for (const b of EX.bricks) b.wake();

  /* Relax at exactly the cadence the run will use, so the pose we freeze is
     the running solver's own fixed point rather than a stiffer solver's. A
     sequential-impulse solver needs roughly one iteration per course to carry
     load to the footing, so a tall wall takes more frames to come to rest than
     a short one; stop on stillness rather than a fixed count, capped so a
     24x16x5 wall cannot stall the page. The cap counts frames, never
     milliseconds, so the settled pose is identical on every machine. */
  const sdt = 1 / (60 * EX.substeps);
  const STILL = 4e-4;                       // (m/s)^2, ~0.02 m/s
  for (let frame = 0; frame < 90; frame++) {
    for (let i = 0; i < EX.substeps; i++) world.step(sdt, EX.velIters, EX.posIters);
    let moving = false;
    for (const b of EX.bricks) {
      if (b.vx * b.vx + b.vy * b.vy > STILL) { moving = true; break; }
    }
    if (!moving) break;
  }

  for (const b of EX.bricks) {
    b.vx = b.vy = b.av = 0;
    b.ox = b.px; b.oy = b.py; b.oang = b.ang;
    b.sleep();
  }
  world.impacts.length = 0;
  world.time = 0;
  world.onManifold = onM;
}

