require('./harness.js');
const X = global.__X;
const { EX, S, DEFAULTS, buildScene } = X;

function scene(over) {
  Object.assign(S, DEFAULTS, over);
  const t0 = process.hrtime.bigint();
  buildScene();
  const build = Number(process.hrtime.bigint() - t0) / 1e6;
  return build;
}

// After the scene is built (and settled), let the untouched wall idle and see
// how far it drifts from the pose the UI is showing.
function idleDrift(seconds) {
  const w = EX.world, sub = EX.substeps, sdt = 1 / 60 / sub;
  for (const b of EX.bricks) b.wake();
  let maxD = 0;
  for (let f = 0; f < seconds * 60; f++) {
    for (let i = 0; i < sub; i++) w.step(sdt, EX.velIters, EX.posIters);
    for (const b of EX.bricks) maxD = Math.max(maxD, Math.hypot(b.px - b.ox, b.py - b.oy));
  }
  return maxD * 1000;
}

const cases = [
  ['default 12x8x2', {}],
  ['tall    12x16x2', { rows: 16 }],
  ['thin     4x16x1', { cols: 4, rows: 16, layers: 1 }],
  ['max     24x16x5', { cols: 24, rows: 16, layers: 5 }],
  ['heavy   12x16x2 12kg', { rows: 16, brickMass: 12 }],
  ['light   12x16x2 0.5kg', { rows: 16, brickMass: 0.5 }],
  ['slick   12x16x2 mu=0', { rows: 16, brickFric: 0 }],
  ['bouncy  12x16x2 e=0.9', { rows: 16, brickRest: 0.9 }],
];

console.log('untouched wall: build cost, then idle drift from the displayed pose');
for (const [name, over] of cases) {
  const ms = scene(over);
  const n = EX.world.dynamics.length;
  const d = idleDrift(3);
  const displaced = X.countDisplaced();
  console.log(`  ${name.padEnd(22)} bodies ${String(n).padStart(4)}  build ${ms.toFixed(0).padStart(4)}ms  idle drift ${d.toFixed(2).padStart(7)}mm  displaced ${displaced}/${EX.bricks.length}`);
}

