    .replace(/const SETTLE_FRAMES = \d+;/, `const SETTLE_FRAMES = ${frames};`)
    .replace(/const SETTLE_DAMP   = [0-9.]+;/, `const SETTLE_DAMP   = ${damp};`);
  if (src === base) throw new Error('settle constants not found');
