/** Car propulsion: a guided sled up to the target speed, released on impact.
 *  The commanded speed is integrated on its own rather than read back off the
 *  body, so drag and rolling resistance cannot bleed the sled below the speed
 *  the operator dialled in — it arrives at exactly S.speed, every time. */
function driveCar(dt) {
  const car = EX.car;
  if (!car.driving) return;
  EX.cmdV = Math.min(S.speed, EX.cmdV + LAUNCH_ACC * dt);
  car.vx = EX.cmdV;
  car.ang = 0; car.av = 0; car.updateRot();   // rails keep it level pre-impact
}

