require('./harness.js');
const X = global.__X;
const { EX, S, DEFAULTS, buildScene, startTest, simulate, PARAMS } = X;

let fails = 0;
const ok = (cond, label, detail = '') => {
  if (!cond) fails++;
  console.log(`  ${cond ? 'PASS' : 'FAIL'}  ${label}${detail ? '  — ' + detail : ''}`);
};

/* ---------- 1. mandated defaults ---------- */
console.log('\n1. mandated default values');
const MANDATED = {
  speed: 22, cols: 12, rows: 8, layers: 2, brickMass: 2.5, brickW: 0.5, brickH: 0.24,
  gravity: 9.81, brickFric: 0.72, brickRest: 0.18, carMass: 1250, carW: 4.2, carH: 1.45,
  groundFric: 0.85, scale: 80,
};
Object.assign(S, DEFAULTS);
for (const [k, v] of Object.entries(MANDATED)) {
  ok(DEFAULTS[k] === v, `${k} = ${v}`, DEFAULTS[k] === v ? '' : `got ${DEFAULTS[k]}`);
}
for (const [key, , , min, max, , def] of PARAMS) {
  if (MANDATED[key] === undefined) continue;
  ok(def >= min && def <= max, `${key} default inside [${min}, ${max}]`);
}

/* ---------- 2. required setting ranges ---------- */
console.log('\n2. required setting ranges');
const RANGES = { speed: [5, 45], cols: [4, 24], rows: [3, 16], layers: [1, 5], brickMass: [0.5, 12] };
for (const [k, [lo, hi]] of Object.entries(RANGES)) {
  const p = PARAMS.find(p => p[0] === k);
  ok(p && p[3] === lo && p[4] === hi, `${k} range ${lo}..${hi}`, p ? `got ${p[3]}..${p[4]}` : 'missing');
}

/* ---------- 3. initial scene before any Test ---------- */
console.log('\n3. initial scene');
Object.assign(S, DEFAULTS);
buildScene();
ok(EX.bricks.length === 200, 'default wall has 200 bricks (12x8x2 running bond)', `got ${EX.bricks.length}`);
ok(EX.car && EX.car.vx === 0, 'car present and stationary before Test');
ok(EX.phase === 'ready', 'phase is "ready" on load');

/* ---------- 4. an untouched wall does not move ---------- */
console.log('\n4. untouched wall stays put');
function idle(seconds) {
  const w = EX.world, sub = EX.substeps, sdt = 1 / 60 / sub;
  let d = 0;
  for (let f = 0; f < seconds * 60; f++) {
    for (let i = 0; i < sub; i++) w.step(sdt, EX.velIters, EX.posIters);
    for (const b of EX.bricks) d = Math.max(d, Math.hypot(b.px - b.ox, b.py - b.oy));
  }
  return d;
}
const asleepDrift = idle(4);
ok(asleepDrift === 0, 'sleeping wall drift over 4 s is exactly 0', `${asleepDrift} m`);
for (const b of EX.bricks) b.wake();
const wokeDrift = idle(4) * 1000;
ok(wokeDrift < 15, 'force-woken wall drift over 4 s < 15 mm', `${wokeDrift.toFixed(2)} mm`);
ok(X.countDisplaced() === 0, 'no bricks reported displaced before impact', `${X.countDisplaced()}`);

/* ---------- 5. determinism ---------- */
console.log('\n5. determinism');
function run(seconds, over) {
  Object.assign(S, DEFAULTS, over || {});
  startTest();
  for (let f = 0; f < seconds * 60; f++) simulate(1 / 60);
  return EX.bricks.map(b => `${b.px.toFixed(12)},${b.py.toFixed(12)},${b.ang.toFixed(12)}`).join('|');
}
const a = run(5), b = run(5), c = run(5);
ok(a === b && b === c, 'three identical runs are bit-identical');
run(5, { speed: 40 });
const d = run(5);
ok(d === a, 'a run at other settings then back reproduces the baseline exactly');

/* ---------- 6. no NaN / Inf anywhere ---------- */
console.log('\n6. numerical health');
function finite(over, seconds) {
  Object.assign(S, DEFAULTS, over || {});
  startTest();
  for (let f = 0; f < seconds * 60; f++) {
    simulate(1 / 60);
    for (const bd of EX.world.dynamics) {
      if (!Number.isFinite(bd.px + bd.py + bd.ang + bd.vx + bd.vy + bd.av)) return false;
    }
  }
  return true;
}
ok(finite({}, 8), 'default run stays finite for 8 s');
ok(finite({ cols: 24, rows: 16, layers: 5, speed: 45, brickMass: 0.5 }, 6), 'max wall / max speed / min mass stays finite');
ok(finite({ cols: 4, rows: 3, layers: 1, speed: 5, brickMass: 12, gravity: 0 }, 6), 'min wall / min speed / zero gravity stays finite');
ok(finite({ brickFric: 0, brickRest: 0.9, rows: 16 }, 6), 'frictionless bouncy wall stays finite');

/* ---------- 7. ground penetration ---------- */
console.log('\n7. nothing falls through the ground');
Object.assign(S, DEFAULTS, { cols: 24, rows: 16, layers: 5, speed: 45 });
startTest();
let worst = 0;
for (let f = 0; f < 8 * 60; f++) {
  simulate(1 / 60);
  for (const bd of EX.world.dynamics) {
    const ext = Math.abs(Math.sin(bd.ang)) * bd.hw + Math.abs(Math.cos(bd.ang)) * bd.hh;
    worst = Math.min(worst, bd.py - ext);
  }
}
ok(worst > -0.02, 'lowest body edge never sinks more than 20 mm below y=0', `${(worst * 1000).toFixed(2)} mm`);

/* ---------- 8. car reaches its commanded speed ---------- */
console.log('\n8. car kinematics');
for (const sp of [5, 22, 45]) {
  Object.assign(S, DEFAULTS, { speed: sp });
  startTest();
  let peak = 0;
  for (let f = 0; f < 60 * 4; f++) { simulate(1 / 60); peak = Math.max(peak, EX.car.vx); }
  ok(Math.abs(peak - sp) < 0.15, `car reaches ${sp} m/s`, `peak ${peak.toFixed(3)} m/s`);
}

/* ---------- 9. parameter sensitivity ---------- */
console.log('\n9. settings visibly change the outcome');
function outcome(over) {
  Object.assign(S, DEFAULTS, over);
  startTest();
  for (let f = 0; f < 60 * 7; f++) simulate(1 / 60);
  let spread = 0;
  for (const bk of EX.bricks) spread = Math.max(spread, bk.px - bk.ox);
  return { pen: EX.penetration, disp: X.countDisplaced(), spread, peakG: EX.peakG, vend: EX.car.vx };
}
const slow = outcome({ speed: 8 }), mid = outcome({ speed: 22 }), fast = outcome({ speed: 45 });
ok(slow.disp < mid.disp && mid.disp < fast.disp, 'faster car displaces more bricks',
   `${slow.disp} < ${mid.disp} < ${fast.disp}`);
ok(slow.spread < mid.spread && mid.spread < fast.spread, 'faster car throws debris further',
   `${slow.spread.toFixed(2)} < ${mid.spread.toFixed(2)} < ${fast.spread.toFixed(2)} m`);
const light = outcome({ brickMass: 0.5 }), heavy = outcome({ brickMass: 12 });
ok(light.disp > heavy.disp, 'lighter bricks are displaced more than heavy ones',
   `${light.disp} vs ${heavy.disp}`);
ok(heavy.vend < light.vend, 'heavier wall slows the car more',
   `car ends at ${heavy.vend.toFixed(2)} vs ${light.vend.toFixed(2)} m/s`);
const thin = outcome({ layers: 1 }), thick = outcome({ layers: 5 });
ok(thick.vend < thin.vend, 'a deeper wall slows the car more',
   `${thick.vend.toFixed(2)} vs ${thin.vend.toFixed(2)} m/s`);
ok(mid.peakG > 1 && mid.peakG < 200, 'peak deceleration is a plausible crash figure',
   `${mid.peakG.toFixed(1)} g`);

/* ---------- 10. momentum ---------- */
console.log('\n10. momentum transfer');
Object.assign(S, DEFAULTS);
startTest();
let pre = 0;
for (let f = 0; f < 60 * 8; f++) {
  simulate(1 / 60);
  if (EX.phase === 'launch') pre = EX.car.vx * S.carMass;
}
const post = EX.car.vx * S.carMass + EX.bricks.reduce((s, bk) => s + bk.mass * bk.vx, 0);
ok(post <= pre + 1e-6, 'system never gains forward momentum', `${pre.toFixed(0)} -> ${post.toFixed(0)} kg m/s`);
ok(EX.car.vx < S.speed, 'car is slowed by the impact', `${EX.car.vx.toFixed(2)} < ${S.speed} m/s`);

/* ---------- 11. energy ---------- */
console.log('\n11. energy is never created');
function energy() {
  let e = 0;
  for (const bd of EX.world.dynamics) {
    e += 0.5 * bd.mass * (bd.vx * bd.vx + bd.vy * bd.vy) + 0.5 * bd.inertia * bd.av * bd.av;
    e += bd.mass * S.gravity * bd.py;
  }
  return e;
}
for (const over of [{}, { rows: 16 }, { cols: 24, rows: 16, layers: 5 }, { rows: 16, brickMass: 12 }]) {
  Object.assign(S, DEFAULTS, over);
  buildScene();
  for (const bd of EX.bricks) bd.wake();
