     ```js
     for (const m of this.manifolds.values()) {
       const A = m.A, B = m.B, nx = m.nx, ny = m.ny;
       if (m.count === 0 || (A.invMass === 0 && B.invMass === 0)) continue;

       /* Both points are measured against the same transform and only then
          applied. Correcting point 0 first would tilt the box before point 1
          is even measured, and that per-manifold bias accumulates into a
          lean that walks a tall stack over. */
       let sImp = 0, sTrqA = 0, sTrqB = 0;
       for (let i = 0; i < m.count; i++) {
         const p = m.pts[i];
         const rax = A.c * p.lax - A.s * p.lay, ray = A.s * p.lax + A.c * p.lay;
         const rbx = B.c * p.lbx - B.s * p.lby, rby = B.s * p.lbx + B.c * p.lby;
         const sep = p.sep + ((B.px + rbx) - (A.px + rax)) * nx
                           + ((B.py + rby) - (A.py + ray)) * ny;
         if (sep < minSep) minSep = sep;

         const C = clamp(BAUMGARTE * (sep + SLOP), -MAX_CORRECT, 0);
         if (C === 0) continue;
         const rnA = rax * ny - ray * nx, rnB = rbx * ny - rby * nx;
         const k = A.invMass + B.invMass + A.invI * rnA * rnA + B.invI * rnB * rnB;
         if (k <= 0) continue;
         const imp = -C / k;
         sImp += imp;
         sTrqA += rax * (imp * ny) - ray * (imp * nx);
         sTrqB += rbx * (imp * ny) - rby * (imp * nx);
       }
       if (sImp === 0 && sTrqA === 0 && sTrqB === 0) continue;
       const ix = sImp * nx, iy = sImp * ny;
       A.px -= ix * A.invMass; A.py -= iy * A.invMass; A.ang -= A.invI * sTrqA;
       B.px += ix * B.invMass; B.py += iy * B.invMass; B.ang += B.invI * sTrqB;
     }
