     **Edit 5 — rewritten `settleWall` inner loop:**
     ```js
     /* Relax with the same iteration counts the run will use, so the pose we
        freeze is the running solver's own fixed point and not a stiffer solver's.
        A sequential-impulse solver carries load down roughly one course per
        iteration, so a tall wall needs more frames to come to rest than a short
        one; stop on stillness, and damp hard between frames so the masonry sinks
        to its resting pose instead of ringing about it. The budget counts frames,
        never milliseconds, so the settled pose is identical on every machine. */
     const STILL = 4e-4;                       // (m/s)^2, ~0.02 m/s
     for (let frame = 0; frame < SETTLE_FRAMES; frame++) {
       world.step(1 / 60, EX.velIters, EX.posIters);
       let moving = false;
       for (const b of EX.bricks) {
         b.vx *= SETTLE_DAMP; b.vy *= SETTLE_DAMP; b.av *= SETTLE_DAMP;
         if (b.vx * b.vx + b.vy * b.vy > STILL) moving = true;
       }
       if (!moving) break;
     }
     ```
