/* Perf probe for ONE configuration, run as its own process.
   Measuring this at the tail of verify.js charged the simulation for the heap
   eleven earlier sections had left behind — 197 ms/frame there against 9.7 ms
   for the identical scene in a clean process. A fresh process per config is the
   only honest way to read this number. Config comes in as argv[2] JSON. */
require('./harness.js');
const { EX, S, DEFAULTS, startTest, simulate } = global.__X;

Object.assign(S, DEFAULTS, JSON.parse(process.argv[2] || '{}'));

const tb = process.hrtime.bigint();
startTest();
const build = Number(process.hrtime.bigint() - tb) / 1e6;

const FRAMES = 240;
for (let f = 0; f < 30; f++) simulate(1 / 60);        // warm the JIT, then measure
const samples = [];
for (let f = 0; f < FRAMES; f++) {
  const t = process.hrtime.bigint();
  simulate(1 / 60);
  samples.push(Number(process.hrtime.bigint() - t) / 1e6);
}
samples.sort((a, b) => a - b);
const pick = q => samples[Math.min(samples.length - 1, Math.floor(samples.length * q))];

process.stdout.write(JSON.stringify({
  n: EX.world.dynamics.length,
  build,
  median: pick(0.5),
  p90: pick(0.9),
  p99: pick(0.99),
  mean: samples.reduce((a, b) => a + b, 0) / samples.length,
}));

