class Grid {
  constructor(cell) {
    this.cell = cell; this.map = new Map(); this.layers = 1;
    this.pool = []; this.poolN = 0;      // recycled buckets, see clear()
  }
  key(gx, gy, layer) { return ((gx + 4096) * 8192 + (gy + 4096)) * 8 + layer; }
  /* Buckets are recycled rather than dropped. Rebuilding the hash from scratch
     each frame meant a fresh array per occupied cell, which at ~1900 bodies is
     half a megabyte per frame handed to the collector — and that comes back as
     a GC pause precisely when the crash is at its busiest and the frame budget
     is already tight. The pool holds at most one frame's worth of buckets. */
  clear() {
    for (const arr of this.map.values()) { arr.length = 0; this.pool[this.poolN++] = arr; }
    this.map.clear();
  }
  insert(b) {
    const c = this.cell;
    const x0 = Math.floor(b.minx / c), x1 = Math.floor(b.maxx / c);
    const y0 = Math.floor(b.miny / c), y1 = Math.floor(b.maxy / c);
    const lo = b.layer < 0 ? 0 : b.layer, hi = b.layer < 0 ? this.layers - 1 : b.layer;
    for (let gx = x0; gx <= x1; gx++) {
      for (let gy = y0; gy <= y1; gy++) {
        for (let L = lo; L <= hi; L++) {
          const k = this.key(gx, gy, L);
          let arr = this.map.get(k);
          if (arr === undefined) {
            arr = this.poolN > 0 ? this.pool[--this.poolN] : [];
            this.map.set(k, arr);
          }
          arr.push(b);
        }
      }
    }
  }
}

