/* A/B the broadphase change over an identical frame window, one fresh process
   per arm (argv[2] = 'new' | 'old', argv[3] = JSON settings override). */
const fs = require('fs');
let src = fs.readFileSync('sim.js', 'utf8');

if (process.argv[2] === 'old') {
  // restore the allocating grid + pairSeen dedup
  src = src.replace(
    /  clear\(\) \{\n    for \(const arr of this\.map\.values\(\)\) \{ arr\.length = 0; this\.pool\[this\.poolN\+\+\] = arr; \}\n    this\.map\.clear\(\);\n  \}/,
    '  clear() { this.map.clear(); }');
  src = src.replace(
    /            arr = this\.poolN > 0 \? this\.pool\[--this\.poolN\] : \[\];\n            this\.map\.set\(k, arr\);/,
    '            arr = []; this.map.set(k, arr);');
  src = src.replace(
    /    else if \(m\.stamp === stamp\) return;\n/, '');
  src = src.replace(
    /    \/\/ dynamic <-> dynamic/,
    '    const seen = new Set();\n    // dynamic <-> dynamic');
  src = src.replace(
    /          this\.narrow\(lo, hi, this\.key\(lo\.id, hi\.id\), stamp\);/,
    '          const k = this.key(lo.id, hi.id);\n          if (seen.has(k)) continue;\n          seen.add(k);\n          this.narrow(lo, hi, k, stamp);');
  fs.writeFileSync('sim.var.js', src);
  fs.writeFileSync('harness.var.js',
    fs.readFileSync('harness.js', 'utf8').replace("readFileSync('sim.js'", "readFileSync('sim.var.js'"));
  require('./harness.var.js');
} else {
  require('./harness.js');
}

const { EX, S, DEFAULTS, startTest, simulate } = global.__X;
Object.assign(S, DEFAULTS, JSON.parse(process.argv[3] || '{}'));

const tb = process.hrtime.bigint(); startTest();
const build = Number(process.hrtime.bigint() - tb) / 1e6;

for (let f = 0; f < 40; f++) simulate(1 / 60);          // warm
global.gc();
const h0 = process.memoryUsage().heapUsed;
const t = [];
for (let f = 0; f < 200; f++) {
  const a = process.hrtime.bigint(); simulate(1 / 60);
  t.push(Number(process.hrtime.bigint() - a) / 1e6);
}
const kb = (process.memoryUsage().heapUsed - h0) / 200 / 1024;
const s = t.slice().sort((a, b) => a - b);
console.log(`  ${process.argv[2].padEnd(4)} n=${EX.world.dynamics.length}  median ${s[100].toFixed(2)}  p90 ${s[180].toFixed(2)}  p99 ${s[198].toFixed(2)}  mean ${(t.reduce((a, b) => a + b) / t.length).toFixed(2)} ms  alloc ${kb.toFixed(0)} KB/f  build ${build.toFixed(0)} ms`);

