/* The box is under load average ~99, so wall-clock is unusable. Count the work
   instead: candidate pairs, narrowphase calls, bucket arrays allocated, and
   constraint-solves. These are deterministic — same numbers on any machine, at
   any load — and they are what the wall-clock is a proxy for anyway.
   argv[2] = 'new' | 'old'. */
const fs = require('fs');
let src = fs.readFileSync('sim.js', 'utf8');
const OLD = process.argv[2] === 'old';

if (OLD) {
  const before = src;
  src = src.replace(
    /  clear\(\) \{\n    for \(const arr of this\.map\.values\(\)\) \{ arr\.length = 0; this\.pool\[this\.poolN\+\+\] = arr; \}\n    this\.map\.clear\(\);\n  \}/,
    '  clear() { this.map.clear(); }');
  src = src.replace(
    /            arr = this\.poolN > 0 \? this\.pool\[--this\.poolN\] : \[\];\n            this\.map\.set\(k, arr\);/,
    '            arr = []; this.map.set(k, arr);');
  src = src.replace(/    else if \(m\.stamp === stamp\) return;\n/, '');
  src = src.replace(/    \/\/ dynamic <-> dynamic/, '    const seen = new Set();\n    // dynamic <-> dynamic');
  src = src.replace(
    /          this\.narrow\(lo, hi, this\.key\(lo\.id, hi\.id\), stamp\);/,
    '          const k = this.key(lo.id, hi.id);\n          if (seen.has(k)) continue;\n          seen.add(k);\n          this.narrow(lo, hi, k, stamp);');
  const edits = before.split('\n').length !== src.split('\n').length;
  if (!edits) throw new Error('old-arm rewrite did not apply — comparison would be meaningless');
}

/* Instrument: count bucket allocations and narrowphase entries. */
src = src.replace(/^function collide\(m\) \{/m, 'function collide(m) {\n  globalThis.__narrow++;');
src = src.replace(/            arr = \[\]; this\.map\.set\(k, arr\);/,
                  '            arr = []; globalThis.__buckets++; this.map.set(k, arr);');
src = src.replace(/            arr = this\.poolN > 0 \? this\.pool\[--this\.poolN\] : \[\];/,
                  '            arr = this.poolN > 0 ? this.pool[--this.poolN] : (globalThis.__buckets++, []);');
if (!/__narrow\+\+/.test(src)) throw new Error('instrumentation failed to apply');

fs.writeFileSync('sim.var.js', src);
fs.writeFileSync('harness.var.js',
  fs.readFileSync('harness.js', 'utf8').replace("readFileSync('sim.js'", "readFileSync('sim.var.js'"));
globalThis.__narrow = 0; globalThis.__buckets = 0;
require('./harness.var.js');

const { EX, S, DEFAULTS, startTest, simulate } = global.__X;
for (const over of [{}, { cols: 24, rows: 16, layers: 5 }]) {
  Object.assign(S, DEFAULTS, over);
  startTest();
  globalThis.__narrow = 0; globalThis.__buckets = 0;
  const F = 200;
  for (let f = 0; f < F; f++) simulate(1 / 60);
  console.log(`  ${process.argv[2].padEnd(3)} ${S.cols}x${S.rows}x${S.layers} n=${String(EX.world.dynamics.length).padStart(4)}` +
    `   narrowphase ${(globalThis.__narrow / F).toFixed(0).padStart(6)}/frame` +
    `   buckets allocated ${(globalThis.__buckets / F).toFixed(1).padStart(7)}/frame`);
}

