function buildPanel() {
  const groups = [];
  for (const p of PARAMS) {
    let g = groups.find((x) => x.name === p[2]);
    if (!g) { g = { name: p[2], items: [] }; groups.push(g); }
    g.items.push(p);
  }
  panelBody.innerHTML = "";
  for (const g of groups) {
    const wrap = document.createElement("div");
    wrap.className = "grp";
    const h = document.createElement("h3");
    h.innerHTML = `<span>${g.name}</span><em>${g.items.length}</em>`;
    wrap.appendChild(h);
    for (const [key, label, , min, max, step, def, unit, dec] of g.items) {
      const ctl = document.createElement("div");
      ctl.className = "ctl";
      ctl.innerHTML =
        `<div class="top"><label for="p-${key}">${label}</label>` +
        `<span class="val" id="v-${key}">${fmt(S[key], dec)}<u>${unit}</u></span></div>` +
        `<input type="range" id="p-${key}" min="${min}" max="${max}" step="${step}" value="${S[key]}">`;
      wrap.appendChild(ctl);
      const input = ctl.querySelector("input");
      controls[key] = { input, ctl, valEl: ctl.querySelector(".val"), dec, unit, def };
      input.addEventListener("input", () => {
        S[key] = parseFloat(input.value);        // only this parameter changes
        syncControl(key);
        buildScene();                            // live preview of the new rig
        setStatus("READY");
        el("report").classList.remove("show");
        el("hint").style.opacity = "1";
      });
    }
    panelBody.appendChild(wrap);
  }
  for (const k in controls) syncControl(k);
}
function syncControl(key) {
  const c = controls[key];
  c.valEl.innerHTML = `${fmt(S[key], c.dec)}<u>${c.unit}</u>`;
  c.ctl.classList.toggle("dirty", Math.abs(S[key] - c.def) > 1e-9);
  c.input.value = String(S[key]);
}

