/* Real-browser check: everything headless node cannot see — rendering, canvas
   resize, slider wiring, rAF frame pacing, and whether the page throws. */
const { chromium } = require('playwright-core');
const path = require('path');

const FILE = 'file://' + path.resolve(
  '/Users/melvynx/Developer/experiments/benchmarks/benchmarks/car-crash/2026-07-25-cc-claude-opus-5-2/index.html');

let fails = 0;
const ok = (cond, name, detail) => {
  console.log(`  ${cond ? 'ok  ' : 'FAIL'}  ${name}${detail ? `  — ${detail}` : ''}`);
  if (!cond) fails++;
};

(async () => {
  const browser = await chromium.launch({
    executablePath: require('os').homedir() +
      '/Library/Caches/ms-playwright/chromium-1228/chrome-mac-arm64/' +
      'Google Chrome for Testing.app/Contents/MacOS/Google Chrome for Testing',
  });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });

  const errors = [];
  page.on('pageerror', e => errors.push('pageerror: ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });

  await page.goto(FILE);
  await page.waitForTimeout(900);

  /* ---------- 1. identity ---------- */
  console.log('\n1. identity');
  ok(await page.title() === 'Claude Opus 5', 'document title is the model name', await page.title());
  const brand = (await page.locator('.brand h1').first().innerText()).trim();
  ok(brand === 'Claude Opus 5', 'visible heading is the model name', brand);

  /* ---------- 2. page is clean ---------- */
  console.log('\n2. runtime health');
  ok(errors.length === 0, 'no console errors or exceptions on load', errors.join(' | ') || 'clean');

  /* ---------- 3. initial paint ---------- */
  console.log('\n3. initial render (before Test)');
  const canvasInfo = await page.evaluate(() => {
    const cv = document.getElementById('cv');
    const r = cv.getBoundingClientRect();
    return { w: cv.width, h: cv.height, cssW: Math.round(r.width), cssH: Math.round(r.height) };
  });
  ok(canvasInfo.w > 0 && canvasInfo.h > 0, 'canvas has a backing store',
     `${canvasInfo.w}x${canvasInfo.h} px for ${canvasInfo.cssW}x${canvasInfo.cssH} css`);
  ok(canvasInfo.w >= canvasInfo.cssW, 'backing store is DPR-scaled (not blurry)',
     `ratio ${(canvasInfo.w / canvasInfo.cssW).toFixed(2)}`);

  /* Sample the pixels: the scene must already show a car and a wall. Count
     distinct colours and check ink is present in the left (car) and right
     (wall) halves of the track, so a blank or half-drawn canvas fails here. */
  const paint = await page.evaluate(() => {
    const cv = document.getElementById('cv');
    const g = cv.getContext('2d');
    const d = g.getImageData(0, 0, cv.width, cv.height).data;
    const colours = new Set();
    let leftInk = 0, rightInk = 0, lit = 0;
    for (let i = 0; i < d.length; i += 4) {
      const px = (i / 4) % cv.width;
      colours.add((d[i] >> 3 << 10) | (d[i + 1] >> 3 << 5) | (d[i + 2] >> 3));
      if (d[i + 3] > 0) lit++;
      const bright = d[i] + d[i + 1] + d[i + 2];
      if (bright > 120) { if (px < cv.width / 2) leftInk++; else rightInk++; }
    }
    return { colours: colours.size, leftInk, rightInk, lit, total: d.length / 4 };
  });
  ok(paint.lit === paint.total, 'canvas fully painted (no transparent gaps)');
  ok(paint.colours > 200, 'scene is richly shaded, not a flat fill', `${paint.colours} distinct colours`);
  ok(paint.leftInk > 500, 'car side of the track has content', `${paint.leftInk} lit px`);
  ok(paint.rightInk > 500, 'wall side of the track has content', `${paint.rightInk} lit px`);

  /* ---------- 4. defaults on screen ---------- */
  console.log('\n4. displayed defaults');
  await page.click('#btn-settings');
  await page.waitForTimeout(250);
  const shown = await page.evaluate(() => {
    const out = {};
    for (const input of document.querySelectorAll('#panel-body input[type=range]')) {
      const k = input.id.replace(/^p-/, '');
      const val = document.getElementById('v-' + k);
      out[k] = { input: input.value, min: input.min, max: input.max,
                 text: val ? val.textContent.trim() : null };
    }
    return out;
  });
  const MANDATE = {
    speed: [22, 5, 45], cols: [12, 4, 24], rows: [8, 3, 16], layers: [2, 1, 5],
    brickMass: [2.5, 0.5, 12], brickW: [0.5], brickH: [0.24], gravity: [9.81],
    brickFric: [0.72], brickRest: [0.18], carMass: [1250], carW: [4.2], carH: [1.45],
    groundFric: [0.85], scale: [80],
  };
  let allDefaults = true, allRanges = true, ranged = 0;
  for (const [k, [def, min, max]] of Object.entries(MANDATE)) {
    const s = shown[k];
    // A missing control fails both checks — an absent slider must never let the
    // range assertion pass by simply having nothing left to disagree with.
    if (!s) { allDefaults = allRanges = false; console.log(`      missing control: ${k}`); continue; }
    if (Number(s.input) !== def) { allDefaults = false; console.log(`      ${k}: shows ${s.input}, want ${def}`); }
    if (!s.text || !s.text.includes(String(def).replace(/\.0+$/, ''))) {
      allDefaults = false; console.log(`      ${k}: readout "${s.text}" does not show ${def}`);
    }
    if (min !== undefined) {
      ranged++;
      if (Number(s.min) !== min || Number(s.max) !== max) {
        allRanges = false; console.log(`      ${k}: range ${s.min}..${s.max}, want ${min}..${max}`);
      }
    }
  }
  ok(allDefaults, `all ${Object.keys(MANDATE).length} mandated defaults shown in the UI`);
  ok(allRanges && ranged === 5, 'all 5 mandated slider ranges correct', `${ranged} range-checked`);

  /* ---------- 5. telemetry present at rest ---------- */
  console.log('\n5. telemetry');
  await page.click('#btn-close');
  await page.waitForTimeout(200);
  const rest = await page.evaluate(() => ({
    speed: document.getElementById('t-speed').textContent.trim(),
    time: document.getElementById('t-time').textContent.trim(),
    moving: document.getElementById('t-moving').textContent.trim(),
    status: document.getElementById('status').textContent.trim(),
  }));
  ok(/^0/.test(rest.speed), 'car speed reads zero at rest', rest.speed);
  ok(/^0/.test(rest.time), 'elapsed time reads zero at rest', rest.time);
  ok(/^0/.test(rest.moving), 'moving bricks reads zero at rest', rest.moving);
  ok(rest.status.length > 0, 'status line populated', rest.status);

  /* ---------- 6. the run ---------- */
  console.log('\n6. test run');
  const before = await page.evaluate(() => window.__probe ? window.__probe() : null);
  await page.click('#btn-test');
  await page.waitForTimeout(420);
  const moving = await page.evaluate(() => ({
    speed: parseFloat(document.getElementById('t-speed').textContent),
    time: parseFloat(document.getElementById('t-time').textContent),
  }));
  ok(moving.speed > 5, 'car is moving shortly after Test', `${moving.speed} m/s`);
  ok(moving.time > 0.1, 'clock is running', `${moving.time} s`);

  await page.waitForTimeout(2200);
  const impact = await page.evaluate(() => ({
    moving: parseInt(document.getElementById('t-moving').textContent),
    disp: document.getElementById('t-disp').textContent.trim(),
    speed: parseFloat(document.getElementById('t-speed').textContent),
  }));
  ok(impact.moving > 0 || impact.disp !== '0', 'bricks responded to the impact',
     `moving ${impact.moving}, displaced ${impact.disp}`);
  ok(impact.speed < 22, 'car lost speed in the crash', `${impact.speed} m/s`);

  /* frame pacing during the busiest part of the run */
  const fps = await page.evaluate(() => new Promise(res => {
    const t = []; let last = performance.now();
    const tick = () => {
      const now = performance.now(); t.push(now - last); last = now;
      if (t.length < 90) requestAnimationFrame(tick);
      else { t.sort((a, b) => a - b); res({ median: t[45], p95: t[85], n: t.length }); }
    };
    requestAnimationFrame(tick);
  }));
  ok(fps.median < 20, 'renders at ~60 fps during the crash', `median frame ${fps.median.toFixed(1)} ms, p95 ${fps.p95.toFixed(1)} ms`);

  await page.waitForTimeout(4000);
  const settled = await page.evaluate(() => ({
    status: document.getElementById('status').textContent.trim(),
    moving: parseInt(document.getElementById('t-moving').textContent),
  }));
  ok(settled.moving === 0, 'debris settles and the sim reports rest', `status "${settled.status}"`);

  /* ---------- 7. reset ---------- */
  console.log('\n7. reset');
  await page.click('#btn-reset');
  await page.waitForTimeout(400);
  const afterReset = await page.evaluate(() => ({
    speed: parseFloat(document.getElementById('t-speed').textContent),
    time: parseFloat(document.getElementById('t-time').textContent),
    moving: parseInt(document.getElementById('t-moving').textContent),
    disp: document.getElementById('t-disp').textContent.trim(),
  }));
  ok(afterReset.speed === 0 && afterReset.time === 0, 'reset returns the clock and car to zero',
     `${afterReset.speed} m/s, ${afterReset.time} s`);
  ok(afterReset.moving === 0, 'reset rebuilds a standing wall', `displaced ${afterReset.disp}`);

  /* ---------- 8. settings actually change the scene ---------- */
  console.log('\n8. settings wiring');
  await page.click('#btn-settings');
  await page.waitForTimeout(200);
  const setSlider = (key, v) => page.evaluate(([k, val]) => {
    const el = document.getElementById('p-' + k);
    el.value = String(val);
    el.dispatchEvent(new Event('input', { bubbles: true }));
  }, [key, v]);

  await setSlider('cols', 20);
  await setSlider('rows', 14);
  await page.waitForTimeout(600);
  const bigger = await page.evaluate(() => {
    const t = k => document.getElementById('v-' + k).textContent.trim();
    return { colsText: t('cols'), rowsText: t('rows'), speedText: t('speed'), massText: t('brickMass') };
  });
  ok(/20/.test(bigger.colsText) && /14/.test(bigger.rowsText),
     'changed values are reflected in the readouts', `${bigger.colsText} / ${bigger.rowsText}`);
  ok(/22/.test(bigger.speedText) && /2\.5/.test(bigger.massText),
     'unrelated parameters untouched by the change', `speed ${bigger.speedText}, mass ${bigger.massText}`);

  /* the canvas must have actually redrawn a taller/wider wall */
  const wallGrew = await page.evaluate(() => {
    const cv = document.getElementById('cv'), g = cv.getContext('2d');
    const d = g.getImageData(0, 0, cv.width, cv.height).data;
    let ink = 0;
    for (let i = 0; i < d.length; i += 4) if (d[i] + d[i + 1] + d[i + 2] > 120) ink++;
    return ink;
  });
  ok(wallGrew > paint.leftInk + paint.rightInk, 'a 20x14 wall paints more than the 12x8 default',
     `${wallGrew} vs ${paint.leftInk + paint.rightInk} lit px`);

  await page.click('#btn-defaults');
  await page.waitForTimeout(500);
  const restored = await page.evaluate(() => {
    const v = k => document.querySelector(`#panel-body [data-key="${k}"] input[type=range]`).value;
    return { cols: v('cols'), rows: v('rows'), speed: v('speed') };
  });
  ok(restored.cols === '12' && restored.rows === '8' && restored.speed === '22',
     'restore-defaults returns the mandated values', JSON.stringify(restored));
  await page.click('#btn-close');

  /* ---------- 9. resize ---------- */
  console.log('\n9. responsive canvas');
  for (const [w, h] of [[1024, 640], [1680, 1050], [820, 560], [1440, 900]]) {
    await page.setViewportSize({ width: w, height: h });
    await page.waitForTimeout(320);
    const r = await page.evaluate(() => {
      const cv = document.getElementById('cv');
      const b = cv.getBoundingClientRect();
      const g = cv.getContext('2d');
      const d = g.getImageData(0, 0, cv.width, cv.height).data;
      let lit = 0;
      for (let i = 3; i < d.length; i += 4) if (d[i] > 0) lit++;
      return { bw: cv.width, bh: cv.height, cw: Math.round(b.width), ch: Math.round(b.height),
               filled: lit === d.length / 4,
               overflow: document.documentElement.scrollWidth > document.documentElement.clientWidth };
    });
    const dprOK = Math.abs(r.bw / r.cw - r.bh / r.ch) < 0.02;
    ok(r.filled && dprOK && !r.overflow, `${w}x${h}: canvas re-fits and repaints`,
       `backing ${r.bw}x${r.bh}, css ${r.cw}x${r.ch}${r.overflow ? ', PAGE OVERFLOWS' : ''}`);
  }

  /* ---------- 10. determinism through the real UI ---------- */
  console.log('\n10. determinism via the UI');
  const runOnce = async () => {
    await page.click('#btn-reset');
    await page.waitForTimeout(250);
    await page.click('#btn-test');
    await page.waitForTimeout(5200);
    return page.evaluate(() => ({
      disp: document.getElementById('t-disp').textContent.trim(),
      report: document.getElementById('report') ? document.getElementById('report').innerText.replace(/\s+/g, ' ').trim() : '',
    }));
  };
  const r1 = await runOnce(), r2 = await runOnce();
  ok(r1.disp === r2.disp && r1.report === r2.report,
     'same settings produce the same outcome through the UI',
     `${r1.disp} vs ${r2.disp}`);

  ok(errors.length === 0, 'still no console errors after the full session',
     errors.slice(0, 3).join(' | ') || 'clean');

  await page.screenshot({ path: 'shot-final.png' });
  await browser.close();
  console.log(fails === 0 ? '\nBROWSER CHECKS PASSED' : `\n${fails} BROWSER CHECK(S) FAILED`);
  process.exit(fails ? 1 : 0);
})().catch(e => { console.error('HARNESS ERROR', e); process.exit(2); });

