/** Camera: follows the action, never rescales the physics. */
const Cam = {
  x: 0, y: 0, s: 80, tx: 0, ty: 0, ts: 80, groundY: 0.78,
  computeTarget() {
    const car = EX.car;
    const needH = Math.max(EX.wallH + 2.2, S.carH + 2.6);
    let s = Math.min(S.scale, (H * 0.62) / needH);

    let cx;
    if (EX.phase === "ready") {
      const left = car.px - S.carW / 2 - 1.4;
      const right = EX.wallX + EX.wallW + 2.2;
      s = Math.min(s, (W * 0.84) / Math.max(4, right - left));
      cx = (left + right) / 2;
    } else {
      // keep debris in frame
      let lo = car.px - S.carW, hi = EX.wallX + EX.wallW;
      const B = EX.bricks;
      for (let i = 0; i < B.length; i++) {
        const b = B[i];
        if (!b.awake) continue;
        if (b.px < lo) lo = b.px;
        if (b.px > hi) hi = b.px;
      }
      const span = Math.max(6, hi - lo + 3.5);
      s = Math.min(s, Math.max(S.scale * 0.4, (W * 0.9) / span));
      const viewW = W / s;
      cx = car.px + viewW * 0.16;
      const wallCx = EX.wallX + EX.wallW / 2;
      if (cx > wallCx + viewW * 0.14) cx = wallCx + viewW * 0.14;
      const dbCx = (lo + hi) / 2;
      if (EX.phase === "settling" || EX.phase === "settled") cx = lerp(cx, dbCx, 0.5);
    }
    this.tx = cx;
    this.ts = s;
    this.ty = Math.max(0, (EX.wallH - 6) * 0.12);
  },
  update(dt) {
    this.computeTarget();
    const k = 1 - Math.pow(0.0009, dt);
    this.x = lerp(this.x, this.tx, k);
    this.y = lerp(this.y, this.ty, k);
    this.s = lerp(this.s, this.ts, k);
  },
  snap() { this.computeTarget(); this.x = this.tx; this.y = this.ty; this.s = this.ts; },
  ox() { return W / 2 - this.x * this.s + FX.shake * (FX.rng() - 0.5); },
  oy() { return H * this.groundY + this.y * this.s + FX.shake * (FX.rng() - 0.5) * 0.7; },
};

function drawBackground(ox, oy, s) {
  const horizon = oy;
  const g = ctx.createLinearGradient(0, 0, 0, horizon);
  g.addColorStop(0, "#080b12");
  g.addColorStop(0.55, "#0d1420");

