/* Try candidate ground-line placements on the live page and shoot each one, so
   the choice is made by looking rather than by arithmetic. */
const { chromium } = require('playwright-core');
const FILE = 'file:///Users/melvynx/Developer/experiments/benchmarks/benchmarks/car-crash/2026-07-25-cc-claude-opus-5-2/index.html';

(async () => {
  const browser = await chromium.launch({
    executablePath: require('os').homedir() +
      '/Library/Caches/ms-playwright/chromium-1228/chrome-mac-arm64/' +
      'Google Chrome for Testing.app/Contents/MacOS/Google Chrome for Testing',
  });
  const page = await browser.newPage({ viewport: { width: 1440, height: 880 } });
  await page.goto(FILE);
  await page.waitForTimeout(800);
  console.log('Cam reachable:', await page.evaluate(() => typeof Cam));

  for (const gy of [0.78, 0.68, 0.60]) {
    await page.evaluate(g => { Cam.groundY = g; }, gy);
    await page.waitForTimeout(300);
    await page.screenshot({ path: `frame-ready-${gy}.png` });
  }

  // settled state at each ground line
  await page.evaluate(() => { Cam.groundY = 0.78; });
  await page.click('#btn-test');
  await page.waitForTimeout(8000);
  for (const gy of [0.78, 0.68, 0.60]) {
    await page.evaluate(g => { Cam.groundY = g; }, gy);
    await page.waitForTimeout(300);
    await page.screenshot({ path: `frame-settled-${gy}.png` });
  }
  await browser.close();
  console.log('framing shots written');
})();

